// Copy the real fixtures into public/sessions/ and write the manifest.
//
// The fixtures are the single source of truth and are generated by the Rust
// crate (`cargo run -p flightstrip-core --example fixtures`). Nothing here
// invents session data; it only copies and summarises.
//
// The catalogue (title + hook prose) lives in web/sessions.json, which is
// hand-written and committed, because the fixtures carry meta.title but no
// hook. That file is deliberately NOT moved to web-legacy/, so this script
// keeps working after the pre-rewrite page is deleted.

import { readFileSync, writeFileSync, mkdirSync, existsSync } from "node:fs";
import { resolve, dirname, basename } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const webRoot = resolve(here, "..");
const repoRoot = resolve(webRoot, "..");

const cataloguePath = resolve(webRoot, "sessions.json");
const fixturesDir = resolve(repoRoot, "fixtures");
const outDir = resolve(webRoot, "public", "sessions");

function fail(message) {
  console.error(`sync-fixtures: ${message}`);
  process.exit(1);
}

if (!existsSync(cataloguePath)) {
  fail(`catalogue not found at ${cataloguePath}`);
}

const catalogue = JSON.parse(readFileSync(cataloguePath, "utf8"));
if (!Array.isArray(catalogue.sessions)) {
  fail("catalogue has no `sessions` array");
}

mkdirSync(outDir, { recursive: true });

const SEVERITY_RANK = { info: 0, warn: 1, critical: 2 };

const manifest = [];

for (const entry of catalogue.sessions) {
  // The catalogue points at the fixtures with a relative path.
  const source = resolve(webRoot, entry.file);
  if (!existsSync(source)) {
    fail(`catalogue references a missing fixture: ${entry.file}`);
  }

  const raw = readFileSync(source, "utf8");
  const session = JSON.parse(raw);

  const id = basename(source).replace(/\.json$/, "");
  const file = `${id}.json`;

  // The demo's severity badge is the worst incident in the session.
  let severity = "info";
  for (const incident of session.incidents ?? []) {
    const rank = SEVERITY_RANK[incident.severity] ?? 0;
    if (rank > (SEVERITY_RANK[severity] ?? 0)) severity = incident.severity;
  }

  writeFileSync(resolve(outDir, file), raw);
  manifest.push({
    id,
    title: entry.name,
    hook: entry.blurb,
    severity,
    file,
  });
}

writeFileSync(
  resolve(outDir, "index.json"),
  JSON.stringify(manifest, null, 2) + "\n",
);

console.log(
  `sync-fixtures: wrote ${manifest.length} session(s) to public/sessions/`,
);
for (const m of manifest) {
  console.log(`  ${m.id.padEnd(16)} ${m.severity.padEnd(9)} ${m.title}`);
}
